import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.CeXt7FPx.js";const p=JSON.parse('{"title":"Privacy and usage counts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md"}'),n={name:"guide/privacy.md"};function o(r,e,d,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="privacy-and-usage-counts" tabindex="-1">Privacy and usage counts <a class="header-anchor" href="#privacy-and-usage-counts" aria-label="Permalink to &quot;Privacy and usage counts&quot;">​</a></h1><p>Tiffin counts installs and daily use, anonymously, to know what to build next. It is on by default and you can turn it off.</p><h2 id="what-is-sent" tabindex="-1">What is sent <a class="header-anchor" href="#what-is-sent" aria-label="Permalink to &quot;What is sent&quot;">​</a></h2><p><code>tiffind</code> sends one <code>install</code> event the first time, then one <code>daily_active</code> event a day. Each has only:</p><ul><li>a random install id (it names this copy of Tiffin, not you)</li><li>the Tiffin version</li><li>the OS and architecture</li><li>how Tiffin was installed (installer, app, archive, Homebrew, ...)</li><li>how many runtimes, services and sites exist (numbers only)</li></ul><p>It never sends names, paths, domains, addresses, environment values, your computer&#39;s name or your user name. Your IP address is not stored.</p><p>Nothing is sent in the first hour, so you can read this and turn it off first. A development build never sends.</p><h2 id="turn-it-off" tabindex="-1">Turn it off <a class="header-anchor" href="#turn-it-off" aria-label="Permalink to &quot;Turn it off&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telemetry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span></span></code></pre></div><p>Or turn off <strong>Settings → Usage counts</strong> in the app, or set <code>TIFFIN_TELEMETRY=0</code> or <code>DO_NOT_TRACK=1</code>. <code>tiffin telemetry</code> shows whether it is on and your install id.</p><p>The docs site has no analytics.</p>',11)])])}const f=a(n,[["render",o]]);export{p as __pageData,f as default};
